function longestOnesWithFlips(bits: number[], k: number): number {
  let best = 0;
  for (let i = 0; i < bits.length; i++) {
    let zeros = 0;
    for (let j = i; j < bits.length; j++) {
      if (bits[j] === 0) zeros++;
      if (zeros > k) break;
      best = Math.max(best, j - i + 1);
    }
  }
  return best;
}

